package com.scriptles.cabinet.profile.controller;
import com.scriptles.cabinet.profile.dto.ClaimResponse; import com.scriptles.cabinet.profile.enums.HQClaimRequestStatus; import com.scriptles.cabinet.profile.service.HQClaimService; import com.scriptles.cabinet.security.AuthenticatedUser; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/v1/moderation/hq-claims") @RequiredArgsConstructor @Validated public class HQModerationController { private final HQClaimService claims; @PutMapping("/{claimId}") public ClaimResponse decide(@AuthenticationPrincipal AuthenticatedUser reviewer,@PathVariable UUID claimId,@RequestParam HQClaimRequestStatus status){return claims.decide(reviewer.id(),claimId,status);} }
